// What php does with bytes that follow a CLOSING enclosure, with and without an escape in play.
$cases = [
    "\"ab\"cd\n",
    "\"ab\"cd,e\n",
    "\"ab\"\"cd\"\n",
    "\"a\\\"\"b\"\n",
    "\"ab\" cd\n",
    "\"ab\"\"\n",
    "\"ab\"c\"d\"\n",
];
foreach ($cases as $i => $text) {
    $h = fopen("php://memory", "w+");
    fwrite($h, $text);
    rewind($h);
    echo "case $i\n";
    while (($row = fgetcsv($h, 0, ",", "\"", "\\")) !== false) {
        var_dump($row);
    }
    fclose($h);
}
